<script setup lang="ts">
import {ref,onMounted,onUnmounted} from 'vue'
import {api} from './api'
const config=ref<any>({base_url:'',model:'',enabled:false,allow_external:false,allow_evidence:false,has_key:false}), key=ref(''), password=ref(''), error=ref(''), notice=ref(''), job=ref<any>(null), busy=ref(false)
let timer:ReturnType<typeof setTimeout>|undefined
async function run(fn:()=>Promise<void>){error.value='';notice.value='';busy.value=true;try{await fn()}catch(e){error.value=e instanceof Error?e.message:String(e)}finally{busy.value=false}}
async function load(){config.value=await api.request('/model/config')}
async function save(){const {base_url,model,enabled,allow_external,allow_evidence}=config.value;await api.put('/model/config',{base_url,model,enabled,allow_external,allow_evidence,...(key.value?{api_key:key.value}:{})});key.value='';await load();notice.value='配置已保存。密钥输入已清空。'}
async function poll(){job.value=await api.request(`/model/jobs/${job.value.id}`);if(['queued','running'].includes(job.value.status))timer=setTimeout(()=>run(poll),1000)}
async function test(){job.value=await api.post('/model/jobs',{purpose:'test'});await poll()}
async function backup(){if(password.value.length<12)throw Error('备份密码至少 12 字符');const blob=await api.post<Blob>('/backup',{password:password.value});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`tcm-backup-${new Date().toISOString().slice(0,10)}.tcmbak`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);password.value='';notice.value='加密备份下载已发起。'}
onMounted(()=>run(load));onUnmounted(()=>{if(timer)clearTimeout(timer)})
</script>
<template><section><div v-if="error" class="error-box" role="alert">{{error}}</div><div v-if="notice" class="notice">{{notice}}</div><div class="settings-grid"><div class="panel"><h2>模型服务</h2><p class="hint">配置后，只有在问诊中点击发送才会请求模型。连接测试只发送固定合成文本。</p><label>API 基址<input v-model="config.base_url" type="url" placeholder="HTTPS 或 HTTP loopback"></label><label>模型名<input v-model="config.model"></label><label>新 API 密钥（留空保留现有密钥）<input v-model="key" type="password" autocomplete="new-password"></label><p class="hint">{{config.has_key?'已保存密钥':'尚未保存密钥'}}</p><label class="check"><input type="checkbox" v-model="config.enabled">启用模型服务</label><label class="check"><input type="checkbox" :checked="config.allow_external && config.allow_evidence" @change="config.allow_external=($event.target as HTMLInputElement).checked;config.allow_evidence=config.allow_external">允许发送必要症状和书证至所配置服务</label><button class="primary" :disabled="busy" @click="run(save)">保存配置</button> <button :disabled="busy" @click="run(test)">测试连接</button><div v-if="job" class="result-card"><strong>连接测试 · {{job.status}}</strong><pre>{{job.text||'暂无输出'}}</pre><p v-if="job.error" class="warning">{{job.error}}</p></div></div><div class="panel"><h2>加密备份</h2><p>备份包含数据库和登记原件，模型密钥不进入备份。</p><label>备份密码（至少 12 字符）<input v-model="password" type="password" autocomplete="new-password"></label><button :disabled="busy||password.length<12" @click="run(backup)">下载加密备份</button><p class="hint">请妥善保管密码；恢复目标目录必须为空。</p></div></div></section></template>
